create type game_role as enum ('camera_home','camera_away','scorer','viewer');
create type sponsor_style as enum ('fullscreen','overlay');
create table organizations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table organizer_users (organization_id uuid references organizations on delete cascade, user_id uuid not null, primary key(organization_id,user_id));
create table broadcast_settings (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations, provider text not null, encrypted_credentials bytea, created_at timestamptz not null default now());
create table games (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations, config jsonb not null, status text not null default 'draft', created_by uuid not null, created_at timestamptz not null default now());
create table game_invitations (id uuid primary key default gen_random_uuid(), game_id uuid not null references games on delete cascade, role game_role not null, token_hash text not null unique, expires_at timestamptz not null, revoked_at timestamptz);
create table camera_assignments (game_id uuid references games on delete cascade, role game_role not null, participant_identity text, orientation text, width int, height int, updated_at timestamptz, primary key(game_id,role));
create table score_events (id uuid primary key default gen_random_uuid(), game_id uuid not null references games on delete cascade, sequence bigint generated always as identity, event_type text not null, payload jsonb not null, actor text not null, created_at timestamptz not null default now(), unique(game_id,sequence));
create table game_states (game_id uuid primary key references games on delete cascade, version bigint not null default 0, state jsonb not null, updated_at timestamptz not null default now());
create table broadcast_sessions (id uuid primary key default gen_random_uuid(), game_id uuid not null references games, provider text not null, provider_session_id text, status text not null, started_at timestamptz, stopped_at timestamptz);
create table health_events (id bigint generated always as identity primary key, game_id uuid not null references games on delete cascade, participant_role game_role, kind text not null, detail jsonb not null default '{}', created_at timestamptz not null default now());
create table sponsor_assets (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations, storage_path text not null, original_name text not null, mime_type text not null, width int not null, height int not null, bytes int not null, created_at timestamptz not null default now(), deleted_at timestamptz);
create table sponsor_libraries (organization_id uuid references organizations on delete cascade, asset_id uuid references sponsor_assets on delete cascade, primary key(organization_id,asset_id));
create table game_sponsors (game_id uuid references games on delete cascade, asset_id uuid references sponsor_assets, position int not null, enabled boolean not null default true, rotation int not null default 0, primary key(game_id,asset_id));
create table sponsor_display_settings (game_id uuid primary key references games on delete cascade, style sponsor_style not null default 'fullscreen', interval_seconds int not null default 4 check(interval_seconds between 3 and 10), mute_during boolean not null default true, safety_timeout_minutes int not null default 30);
create table sponsor_display_sessions (id uuid primary key default gen_random_uuid(), game_id uuid not null references games, active boolean not null, started_at timestamptz not null default now(), stopped_at timestamptz, anchor_asset_id uuid references sponsor_assets, rotation_offset int not null default 0, paused_at timestamptz);
create table sponsor_audit_events (id bigint generated always as identity primary key, session_id uuid references sponsor_display_sessions, actor text not null, action text not null, created_at timestamptz not null default now());
alter table organizations enable row level security; alter table sponsor_assets enable row level security; alter table games enable row level security;
-- Production policies bind auth.uid() to organizer_users. Service-role access stays server-side only.
